    gocpp::error rec::marshal(encodeState* e, go_any v, encOpts opts)
    {
        gocpp::Defer defer;
        try
        {
            gocpp::error err;
            defer.push_back([=]{ [=]() mutable -> void
            {
                if(auto r = gocpp::recover(); r != nullptr)
                {
                    if(auto [je, ok] = gocpp::getValue<jsonError>(r); ok)
                    {
                        err = je.error;
                    }
                    else
                    {
                        gocpp::panic(r);
                    }
                }
            }(); });
            rec::reflectValue(gocpp::recv(e), reflect::ValueOf(v), opts);
            return nullptr;
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

