    bool isEmptyValue(reflect::Value v)
    {
        //Go switch emulation
        {
            auto condition = rec::Kind(gocpp::recv(v));
            int conditionId = -1;
            if(condition == reflect::Array) { conditionId = 0; }
            else if(condition == reflect::Map) { conditionId = 1; }
            else if(condition == reflect::Slice) { conditionId = 2; }
            else if(condition == reflect::String) { conditionId = 3; }
            else if(condition == reflect::Bool) { conditionId = 4; }
            else if(condition == reflect::Int) { conditionId = 5; }
            else if(condition == reflect::Int8) { conditionId = 6; }
            else if(condition == reflect::Int16) { conditionId = 7; }
            else if(condition == reflect::Int32) { conditionId = 8; }
            else if(condition == reflect::Int64) { conditionId = 9; }
            else if(condition == reflect::Uint) { conditionId = 10; }
            else if(condition == reflect::Uint8) { conditionId = 11; }
            else if(condition == reflect::Uint16) { conditionId = 12; }
            else if(condition == reflect::Uint32) { conditionId = 13; }
            else if(condition == reflect::Uint64) { conditionId = 14; }
            else if(condition == reflect::Uintptr) { conditionId = 15; }
            else if(condition == reflect::Float32) { conditionId = 16; }
            else if(condition == reflect::Float64) { conditionId = 17; }
            else if(condition == reflect::Interface) { conditionId = 18; }
            else if(condition == reflect::Pointer) { conditionId = 19; }
            switch(conditionId)
            {
                case 0:
                case 1:
                case 2:
                case 3:
                    return rec::Len(gocpp::recv(v)) == 0;
                    break;
                case 4:
                case 5:
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                case 11:
                case 12:
                case 13:
                case 14:
                case 15:
                case 16:
                case 17:
                case 18:
                case 19:
                    return rec::IsZero(gocpp::recv(v));
                    break;
            }
        }
        return false;
    }

