    {
        return value.PrintTo(os);
    }

    
    template<typename T> requires gocpp::GoStruct<T>
    structFields::operator T()
    {
        T result;
        result.list = this->list;
        result.byExactName = this->byExactName;
        result.byFoldedName = this->byFoldedName;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool structFields::operator==(const T& ref) const
    {
        if (list != ref.list) return false;
        if (byExactName != ref.byExactName) return false;
        if (byFoldedName != ref.byFoldedName) return false;
        return true;
    }

    std::ostream& structFields::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << list;
        os << " " << byExactName;
        os << " " << byFoldedName;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct structFields& value)
    {
        return value.PrintTo(os);
    }

    void rec::encode(structEncoder se, encodeState* e, reflect::Value v, encOpts opts)
    {
        auto next = (unsigned char)('{');
        FieldLoop:
        for(auto [i, gocpp_ignored] : se.fields.list)
        {
            if(false) {
            FieldLoop_continue:
                continue;
            FieldLoop_break:
                break;
            }
            auto f = & se.fields.list[i];

            // Find the nested struct field by following f.index.
            auto fv = v;
            for(auto [gocpp_ignored, i] : f->index)
            {
                if(rec::Kind(gocpp::recv(fv)) == reflect::Pointer)
                {
                    if(rec::IsNil(gocpp::recv(fv)))
                    {
                        goto FieldLoop_continue;
                    }
                    fv = rec::Elem(gocpp::recv(fv));
                }
                fv = rec::Field(gocpp::recv(fv), i);
            }

            if(f->omitEmpty && isEmptyValue(fv))
            {
                continue;
            }
            rec::WriteByte(gocpp::recv(e), next);
            next = ',';
            if(opts.escapeHTML)
            {
                rec::WriteString(gocpp::recv(e), f->nameEscHTML);
            }
            else
            {
                rec::WriteString(gocpp::recv(e), f->nameNonEsc);
            }
            opts.quoted = f->quoted;
            f->encoder(e, fv, opts);
        }
        if(next == '{')
        {
            rec::WriteString(gocpp::recv(e), "{}"_s);
        }
        else
        {
            rec::WriteByte(gocpp::recv(e), '}');
        }
    }

    encoderFunc newStructEncoder(reflect::Type t)
    {
        auto se = gocpp::Init<structEncoder>([=](auto& x) {
            x.fields = cachedTypeFields(t);
        });
        return [&](auto x, auto y, auto z){ return rec::encode(se, x, y, z); };
    }

    
