    struct gocpp_id_3
            {

                using isGoStruct = void;

                template<typename T> requires gocpp::GoStruct<T>
                operator T()
                {
                    T result;
                    return result;
                }

                template<typename T> requires gocpp::GoStruct<T>
                bool operator==(const T& ref) const
                {
                    return true;
                }

                std::ostream& PrintTo(std::ostream& os) const
                {
                    os << '{';
                    os << '}';
                    return os;
                }
            };

            std::ostream& operator<<(std::ostream& os, const struct gocpp_id_3& value)
            {
                return value.PrintTo(os);
            }


    void rec::encode(mapEncoder me, encodeState* e, reflect::Value v, encOpts opts)
    {
        gocpp::Defer defer;
        try
        {
            if(rec::IsNil(gocpp::recv(v)))
            {
                rec::WriteString(gocpp::recv(e), "null"_s);
                return;
            }
            if(e->ptrLevel++; e->ptrLevel > startDetectingCyclesAfter)
            {
                // We're a large number of nested ptrEncoder.encode calls deep;
                // start checking if we've run into a pointer cycle.
                auto ptr = rec::UnsafePointer(gocpp::recv(v));
                if(auto [gocpp_id_2, ok] = e->ptrSeen[ptr]; ok)
                {
                    rec::error(gocpp::recv(e), new UnsupportedValueError {v, mocklib::Sprintf("encountered a cycle via %s"_s, rec::Type(gocpp::recv(v)))});
                }
                e->ptrSeen[ptr] = gocpp_id_3 {};
                defer.push_back([=]{ remove(e->ptrSeen, ptr); });
            }
            rec::WriteByte(gocpp::recv(e), '{');

            // Extract and sort the keys.
            auto sv = gocpp::make(gocpp::Tag<gocpp::slice<reflectWithString>>(), rec::Len(gocpp::recv(v)));
            auto mi = rec::MapRange(gocpp::recv(v));
            gocpp::error err = rec::MapRange(gocpp::recv(v));
            for(auto i = 0; rec::Next(gocpp::recv(mi)); i++)
            {
                if(std::tie(sv[i].ks, err) = resolveKeyName(rec::Key(gocpp::recv(mi))); err != nullptr)
                {
                    rec::error(gocpp::recv(e), mocklib::Errorf("json: encoding error for type %q: %q"_s, rec::String(gocpp::recv(rec::Type(gocpp::recv(v)))), rec::Error(gocpp::recv(err))));
                }
                sv[i].v = rec::Value(gocpp::recv(mi));
            }
            slices::SortFunc(sv, [=](reflectWithString i, reflectWithString j) mutable -> int
            {
                return strings::Compare(i.ks, j.ks);
            });

            for(auto [i, kv] : sv)
            {
                if(i > 0)
                {
                    rec::WriteByte(gocpp::recv(e), ',');
                }
                rec::Write(gocpp::recv(e), appendString(rec::AvailableBuffer(gocpp::recv(e)), kv.ks, opts.escapeHTML));
                rec::WriteByte(gocpp::recv(e), ':');
                me.elemEnc(e, kv.v, opts);
            }
            rec::WriteByte(gocpp::recv(e), '}');
            e->ptrLevel--;
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    encoderFunc newMapEncoder(reflect::Type t)
    {
        //Go switch emulation
        {
            auto condition = rec::Kind(gocpp::recv(rec::Key(gocpp::recv(t))));
            int conditionId = -1;
            if(condition == reflect::String) { conditionId = 0; }
            else if(condition == reflect::Int) { conditionId = 1; }
            else if(condition == reflect::Int8) { conditionId = 2; }
            else if(condition == reflect::Int16) { conditionId = 3; }
            else if(condition == reflect::Int32) { conditionId = 4; }
            else if(condition == reflect::Int64) { conditionId = 5; }
            else if(condition == reflect::Uint) { conditionId = 6; }
            else if(condition == reflect::Uint8) { conditionId = 7; }
            else if(condition == reflect::Uint16) { conditionId = 8; }
            else if(condition == reflect::Uint32) { conditionId = 9; }
            else if(condition == reflect::Uint64) { conditionId = 10; }
            else if(condition == reflect::Uintptr) { conditionId = 11; }
            switch(conditionId)
            {
                case 0:
                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                case 11:
                    break;
                default:
                    if(! rec::Implements(gocpp::recv(rec::Key(gocpp::recv(t))), textMarshalerType))
                    {
                        return unsupportedTypeEncoder;
                    }
                    break;
            }
        }
        auto me = mapEncoder {typeEncoder(rec::Elem(gocpp::recv(t)))};
        return [&](auto x, auto y, auto z){ return rec::encode(me, x, y, z); };
    }

    void encodeByteSlice(encodeState* e, reflect::Value v, encOpts _1)
    {
        if(rec::IsNil(gocpp::recv(v)))
        {
            rec::WriteString(gocpp::recv(e), "null"_s);
            return;
        }

        auto s = rec::Bytes(gocpp::recv(v));
        auto b = rec::AvailableBuffer(gocpp::recv(e));
        b = append(b, '"');
        b = rec::AppendEncode(gocpp::recv(base64::StdEncoding), b, s);
        b = append(b, '"');
        rec::Write(gocpp::recv(e), b);
    }

