    void rec::encode(sliceEncoder se, encodeState* e, reflect::Value v, encOpts opts)
    {
        gocpp::Defer defer;
        try
        {
            if(rec::IsNil(gocpp::recv(v)))
            {
                rec::WriteString(gocpp::recv(e), "null"_s);
                return;
            }
            if(e->ptrLevel++; e->ptrLevel > startDetectingCyclesAfter)
            {
                // We're a large number of nested ptrEncoder.encode calls deep;
                // start checking if we've run into a pointer cycle.
                // Here we use a struct to memorize the pointer to the first element of the slice
                // and its length.
                auto ptr_tmp = gocpp_id_4 {rec::UnsafePointer(gocpp::recv(v)), rec::Len(gocpp::recv(v))};
                auto& ptr = ptr_tmp;
                if(auto [gocpp_id_5, ok] = e->ptrSeen[ptr]; ok)
                {
                    rec::error(gocpp::recv(e), new UnsupportedValueError {v, mocklib::Sprintf("encountered a cycle via %s"_s, rec::Type(gocpp::recv(v)))});
                }
                e->ptrSeen[ptr] = gocpp_id_6 {};
                defer.push_back([=]{ remove(e->ptrSeen, ptr); });
            }
            se.arrayEnc(e, v, opts);
            e->ptrLevel--;
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    encoderFunc newSliceEncoder(reflect::Type t)
    {
        // Byte slices get special treatment; arrays don't.
        if(rec::Kind(gocpp::recv(rec::Elem(gocpp::recv(t)))) == reflect::Uint8)
        {
            auto p = reflect::PointerTo(rec::Elem(gocpp::recv(t)));
            if(! rec::Implements(gocpp::recv(p), marshalerType) && ! rec::Implements(gocpp::recv(p), textMarshalerType))
            {
                return encodeByteSlice;
            }
        }
        auto enc = sliceEncoder {newArrayEncoder(t)};
        return [&](auto x, auto y, auto z){ return rec::encode(enc, x, y, z); };
    }

    
