    void rec::encode(arrayEncoder ae, encodeState* e, reflect::Value v, encOpts opts)
    {
        rec::WriteByte(gocpp::recv(e), '[');
        auto n = rec::Len(gocpp::recv(v));
        for(auto i = 0; i < n; i++)
        {
            if(i > 0)
            {
                rec::WriteByte(gocpp::recv(e), ',');
            }
            ae.elemEnc(e, rec::Index(gocpp::recv(v), i), opts);
        }
        rec::WriteByte(gocpp::recv(e), ']');
    }

