    bool isValidTag(gocpp::string s)
    {
        if(s == ""_s)
        {
            return false;
        }
        for(auto [gocpp_ignored, c] : s)
        {
            //Go switch emulation
            {
                int conditionId = -1;
                if(strings::ContainsRune("!#$%&()*+-./:;<=>?@[]^_{|}~ "_s, c)) { conditionId = 0; }
                else if(! unicode::IsLetter(c) && ! unicode::IsDigit(c)) { conditionId = 1; }
                switch(conditionId)
                {
                    case 0:
                        break;
                    // Backslash and quote chars are reserved, but
                    // otherwise any punctuation chars are allowed
                    // in a tag name.
                    case 1:
                        return false;
                        break;
                }
            }
        }
        return true;
    }

    reflect::Type typeByIndex(reflect::Type t, gocpp::slice<int> index)
    {
        for(auto [gocpp_ignored, i] : index)
        {
            if(rec::Kind(gocpp::recv(t)) == reflect::Pointer)
            {
                t = rec::Elem(gocpp::recv(t));
            }
            t = rec::Field(gocpp::recv(t), i).Type;
        }
        return t;
    }

    
