    std::tuple<gocpp::string, gocpp::error> resolveKeyName(reflect::Value k)
    {
        if(rec::Kind(gocpp::recv(k)) == reflect::String)
        {
            return {rec::String(gocpp::recv(k)), nullptr};
        }
        if(auto [tm, ok] = gocpp::getValue<encoding::TextMarshaler>(rec::Interface(gocpp::recv(k))); ok)
        {
            if(rec::Kind(gocpp::recv(k)) == reflect::Pointer && rec::IsNil(gocpp::recv(k)))
            {
                return {""_s, nullptr};
            }
            auto [buf, err] = rec::MarshalText(gocpp::recv(tm));
            return {gocpp::string(buf), err};
        }
        //Go switch emulation
        {
            auto condition = rec::Kind(gocpp::recv(k));
            int conditionId = -1;
            if(condition == reflect::Int) { conditionId = 0; }
            else if(condition == reflect::Int8) { conditionId = 1; }
            else if(condition == reflect::Int16) { conditionId = 2; }
            else if(condition == reflect::Int32) { conditionId = 3; }
            else if(condition == reflect::Int64) { conditionId = 4; }
            else if(condition == reflect::Uint) { conditionId = 5; }
            else if(condition == reflect::Uint8) { conditionId = 6; }
            else if(condition == reflect::Uint16) { conditionId = 7; }
            else if(condition == reflect::Uint32) { conditionId = 8; }
            else if(condition == reflect::Uint64) { conditionId = 9; }
            else if(condition == reflect::Uintptr) { conditionId = 10; }
            switch(conditionId)
            {
                case 0:
                case 1:
                case 2:
                case 3:
                case 4:
                    return {strconv::FormatInt(rec::Int(gocpp::recv(k)), 10), nullptr};
                    break;
                case 5:
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                    return {strconv::FormatUint(rec::Uint(gocpp::recv(k)), 10), nullptr};
                    break;
            }
        }
        gocpp::panic("unexpected map key type"_s);
    }

    template<typename Bytes>
    gocpp::slice<unsigned char> appendString(gocpp::slice<unsigned char> dst, Bytes src, bool escapeHTML)
    {
        dst = append(dst, '"');
        auto start = 0;
        for(auto i = 0; i < len(src); )
        {
            if(auto b = src[i]; b < utf8::RuneSelf)
            {
                if(htmlSafeSet[b] || (! escapeHTML && safeSet[b]))
                {
                    i++;
                    continue;
                }
                dst = append(dst, src.make_slice(start, i));
                //Go switch emulation
                {
                    auto condition = b;
                    int conditionId = -1;
                    if(condition == '\\') { conditionId = 0; }
                    else if(condition == '"') { conditionId = 1; }
                    else if(condition == '\b') { conditionId = 2; }
                    else if(condition == '\f') { conditionId = 3; }
                    else if(condition == '\n') { conditionId = 4; }
                    else if(condition == '\r') { conditionId = 5; }
                    else if(condition == '\t') { conditionId = 6; }
                    switch(conditionId)
                    {
                        case 0:
                        case 1:
                            dst = append(dst, '\\', b);
                            break;
                        case 2:
                            dst = append(dst, '\\', 'b');
                            break;
                        case 3:
                            dst = append(dst, '\\', 'f');
                            break;
                        case 4:
                            dst = append(dst, '\\', 'n');
                            break;
                        case 5:
                            dst = append(dst, '\\', 'r');
                            break;
                        case 6:
                            dst = append(dst, '\\', 't');
                            break;
                        default:
                            // This encodes bytes < 0x20 except for \b, \f, \n, \r and \t.
                            // If escapeHTML is set, it also escapes <, >, and &
                            // because they can lead to security holes when
                            // user-controlled strings are rendered into JSON
                            // and served to some browsers.
                            dst = append(dst, '\\', 'u', '0', '0', hex[b >> 4], hex[b & 0xF]);
                            break;
                    }
                }
                i++;
                start = i;
                continue;
            }
            // TODO(https://go.dev/issue/56948): Use generic utf8 functionality.
            // For now, cast only a small portion of byte slices to a string
            // so that it can be stack allocated. This slows down []byte slightly
            // due to the extra copy, but keeps string performance roughly the same.
            auto n = len(src) - i;
            if(n > utf8::UTFMax)
            {
                n = utf8::UTFMax;
            }
            auto [c, size] = utf8::DecodeRuneInString(gocpp::string(src.make_slice(i, i + n)));
            if(c == utf8::RuneError && size == 1)
            {
                dst = append(dst, src.make_slice(start, i));
                dst = append(dst, "\\ufffd"_s);
                i += size;
                start = i;
                continue;
            }
            // U+2028 is LINE SEPARATOR.
            // U+2029 is PARAGRAPH SEPARATOR.
            // They are both technically valid characters in JSON strings,
            // but don't work in JSONP, which has to be evaluated as JavaScript,
            // and can lead to security holes there. It is valid JSON to
            // escape them, so we do so unconditionally.
            // See https://en.wikipedia.org/wiki/JSON#Safety.
            if(c == '\u2028' || c == '\u2029')
            {
                dst = append(dst, src.make_slice(start, i));
                dst = append(dst, '\\', 'u', '2', '0', '2', hex[c & 0xF]);
                i += size;
                start = i;
                continue;
            }
            i += size;
        }
        dst = append(dst, src.make_slice(start));
        dst = append(dst, '"');
        return dst;
    }

    // A field represents a single field found in a struct.
    
    template<typename T> requires gocpp::GoStruct<T>
    field::operator T()
    {
        T result;
        result.name = this->name;
        result.nameBytes = this->nameBytes;
        result.nameNonEsc = this->nameNonEsc;
        result.nameEscHTML = this->nameEscHTML;
        result.tag = this->tag;
        result.index = this->index;
        result.typ = this->typ;
        result.omitEmpty = this->omitEmpty;
        result.quoted = this->quoted;
        result.encoder = this->encoder;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool field::operator==(const T& ref) const
    {
        if (name != ref.name) return false;
        if (nameBytes != ref.nameBytes) return false;
        if (nameNonEsc != ref.nameNonEsc) return false;
        if (nameEscHTML != ref.nameEscHTML) return false;
        if (tag != ref.tag) return false;
        if (index != ref.index) return false;
        if (typ != ref.typ) return false;
        if (omitEmpty != ref.omitEmpty) return false;
        if (quoted != ref.quoted) return false;
        if (encoder != ref.encoder) return false;
        return true;
    }

